class Translator:
    def __init__(self, language: str = "pt-BR"):
        self.language = language if language in STRINGS else "pt-BR"

    def __call__(self, key: str, **kwargs) -> str:
        value = STRINGS.get(self.language, {}).get(key)
        if value is None:
            value = STRINGS["pt-BR"].get(key, key)
        try:
            return value.format(**kwargs)
        except Exception:
            return value
